  'store2a.refusal.farmer': 'لا يُعرض اسم المزارع ولا صورته ولا رقم عضويته ولا حيازته من الأرض ولا تاريخ «يبيع منذ» — المنظمة هي البائع.',
  'store2a.refusal.badges': 'لا تُعرض شارة «موثّق KYC» ولا «بائع مصنّف في المركز» ولا شارة مبيعات مكتملة — لا يُسجَّل شيء منها للمنظمة.',
  'store2a.refusal.translated': 'تُعرض المراجعات باللغة التي كُتبت بها — ولا تُترجم.',
  'store2a.refusal.fifo': 'لا تُعرض أرقام الدفعات الإنتاجية ولا تواريخ الانتهاء، ولا وعد بإرسال الأقدم أولًا — لا تُطابَق أي دفعة إنتاجية مع طلب بعد.',
  'store2a.refusal.mrp': 'لا يُدّعى حد أقصى لسعر التجزئة — لا يُسجَّل MRP لهذه المنتجات.',
  'store2a.refusal.age': 'لا يُجرى أي تحقق من العمر في هذه الصفحة.',
