  'store6.queued.lead': 'الدفع، المزايدة، الرد على عرض، تأكيد التسليم — كل ما ينقل أموالًا أو يقطع وعدًا مُلزمًا يحتاج إلى إجابة مباشرة من الخادم. بدون إشارة تقول هذه الأزرار ذلك، مع السبب، ولا يُحفظ شيء ليُرسَل لاحقًا.',
