  'store6.install.how.iphone': 'على iPhone، في Safari: اضغط «مشاركة»، ثم «إضافة إلى الشاشة الرئيسية».',
  'store6.install.how.other': 'المتصفحات الأخرى فيها الخطوة نفسها في قائمتها. إذا لم يكن في متصفحك ذلك، فإن {name} يعمل بالطريقة نفسها في المتصفح.',
