  'store6.install.update': 'يُحدّث نفسه بلطف: عندما يكون إصدار جديد جاهزًا نخبرك — اضغط للتحديث الآن، أو يُطبَّق في المرة التالية التي تفتحه فيها. ولا يحدث ذلك أبدًا في منتصف نموذج تملؤه.',
  'store6.install.language': 'يعمل بلغتك — اللغة التي تستخدمها عند التثبيت. إذا غيّرت اللغة لاحقًا، يتبعها التطبيق المثبّت من المرة التالية التي تفتحه فيها.',
