  'store6.install.storage.full': 'إذا كان الهاتف ممتلئًا تقريبًا، لا يتوقف شيء هنا عن العمل: الصفحات نصوص، والصور لا تُخزَّن أبدًا.',
  'store6.refusal.willSync': 'الإضافة إلى السلة لا «تُزامَن لاحقًا» أبدًا: بدون إشارة تقول إنها تحتاج إلى إشارة، ولا يُحفظ شيء على الهاتف.',
  'store6.refusal.readingOrders': 'طلباتك ورسائلك لا تُحفظ على الهاتف — على هاتف مشترك سيقرؤها شخص آخر.',
  'store6.refusal.actionQueues': 'لا شيء يدخل قائمة انتظار: في الصفحة المحفوظة، كل زر يحتاج إلى الخادم يقول «يحتاج إلى إشارة».',
  'store6.refusal.freshLoading': 'لا شيء يُحمَّل «خلف الشريط»: لا يوجد وضع بطيء، فقط صفحة مباشرة أو صفحة محفوظة مع عمرها.',
  'store6.refusal.otherApp': 'لا يُعلَن هنا عن أي تطبيق آخر: ما تثبّته هو هذا المتجر، من متصفحك.',
  'store6.refusal.queueDrawer': 'لا توجد قائمة انتظار على هذا الهاتف — لا قائمة «في الانتظار» أو «جارٍ الإرسال…» أو «مؤكَّد» أو «فشل — يحتاج إليك»، لأنه لا يُحفظ شيء ليُرسَل لاحقًا.',
  'store6.refusal.waitingChip': 'لا يُعرض عدد «بانتظار المزامنة»: لا شيء ينتظر.',
  'store6.refusal.undoFix': 'لا يوجد «تراجع» أو «إصلاح» على عنصر في قائمة الانتظار — لا توجد عناصر في قائمة الانتظار.',
  'store6.refusal.replay': 'لا يُعاد تشغيل شيء، بأي ترتيب: أنت تضغط الزر بنفسك في صفحة مباشرة، وتُرسَل تلك الضغطة مرة واحدة.',
  'store6.refusal.expireAsk': 'لا تُحفظ قائمة انتظار لتنتهي صلاحيتها: السؤال الوحيد بعد أسبوع يتعلق بمسوداتك غير المرسلة، في صفحة «على هذا الهاتف».',
  'store6.refusal.cartQueue': 'تغييرات سلتك لا تدخل قائمة انتظار: أضف إليها أو غيّرها عند توفر الإشارة، بالسعر المعروض حينها.',
  'store6.refusal.listingDrafts': 'مسودات العروض وصورها من عمل البائع — لا تُكتب في هذه الصفحة.',
  'store6.refusal.namedPerson': 'تذهب الرسائل إلى المنظمة، وليس إلى شخص بعينه أبدًا، ولا تُرسَل رسالة صوتية — ولا يُرسَل شيء لاحقًا وحده.',
