  'help.a5': 'سجل رحلة الدفعة، كما احتفظت به منظمتها — لا يُظهر شخصًا أبدًا، ولا ما تقاضاه أي أحد. اكتب الرمز المطبوع أسفل رمز QR لفتحه.',
  'help.q6': 'هل يمكنني التحقق من السجل بنفسي؟',
  'help.a6': 'نعم. كل سجل تتبع فيه خطوة «تحقق من السجل بنفسك» تُظهر تجزئة كل خطوة وكيفية إعادة حسابها، فلا تحتاج إلى أخذ كلام أحد على محمل الثقة.',
  'help.q7': 'ماذا يغطي وعد الجودة؟',
  'help.a7': 'ما يحمي طلبك، قاعدة تلو الأخرى، كما يعمل فعلًا — وما ليس موعودًا به.',
  'help.q8': 'ما هو EMD، ومتى يُعاد؟',
  'help.a8': 'EMD (تأمين الجدية) يُحتجز من محفظتك عند تقديم أول مزايدة لك في مزاد يطلبه — مبلغ ثابت أو حصة من قيمة الدفعة، كما يعرض المزاد. يُفرج عنه إذا لم تفز، ويُخصم من فاتورتك إذا فزت ودفعت، وتحتفظ به المنظمة إذا فزت ولم تدفع الرصيد في الوقت المحدد.',
  'help.q9': 'لماذا تمتد ساعة المزاد أحيانًا في النهاية؟',
  'help.a9': 'المزايدة في الدقائق الأخيرة من المزاد تمدّده، حتى لا يفوز أحد بالمزايدة في الثانية الأخيرة. الساعة التي تراها هي ساعة الخادم.',
  'help.q10': 'كيف أقدّم عرضًا؟',
  'help.a10': 'في دفعة تقبل العروض، اقترح سعرك وكميتك. يمكن للمنظمة القبول أو تقديم عرض مقابل أو الرفض خلال الوقت المعروض — والصمت لا يعني الموافقة أبدًا. العرض المقبول يصبح طلبًا بالسعر المتفق عليه.',
  'help.q11': 'هل يمكنني استخدام هذا بلغتي؟',
  'help.a11': 'نعم. اختر لغة من صفحة اللغة، أو من القائمة أعلى كل صفحة. لغة حسابك، التي تستخدمها إشعاراتك، موجودة في صفحة تفضيلاتك.',
  'help.platform.q': 'كيف تفتح منظمة متجرها الخاص؟',
  'help.platform.a': 'يمكن للمنظمة فتح واجهة متجرها بنفسها — دون حاجة إلى مكالمة أو مكتب.',
  'help.link.orders': 'طلباتك',
