  'help.contactTitle': 'هل ما زلت بحاجة إلى مساعدة؟',
  'help.contactStore': 'راسل المنظمة بشأن طلب أو دفعة.',
  'about.vision': 'من المزرعة إلى المستقبل.',
  'about.visionNote': 'رؤيتنا — إلى أين نتجه، وليست قائمة بما هو مفعّل اليوم.',
  'about.countsTitle': 'المنصة اليوم',
  'about.countsCadence': 'يُعاد حساب هذه الأعداد كل {minutes} دقيقة — إنها معدودة، وليست مقدّرة أبدًا.',
  'about.principlesTitle': 'ما نلتزم به — حيث يجعله الكود حقيقيًا',
  'about.principle1.title': 'السجل مفتوح؛ والمال خاص.',
  'about.principle1.body': 'التتبع العام يُظهر رحلة الدفعة، مسلسلة بالتجزئة ليتمكن أي شخص من التحقق منها — لا يُظهر شخصًا أبدًا، ولا روبية واحدة.',
  'about.principle2.title': 'الثقة تُبنى هندسيًا، لا تُوعد.',
  'about.principle2.body': 'سجلات التتبع مسلسلة بالتجزئة. الدفعة المدفوعة عبر الإنترنت تُسجَّل في حساب الضمان ويُفرج عنها بقاعدة. يُفتح النزاع كتابةً حيث تفعّل المنظمة النزاعات. وحيث لا نستطيع إثبات شيء، نقول ذلك.',
  'about.principle3.title': 'لا أحد أصغر من أن يُحسب له حساب.',
  'about.principle3.body': 'وضع كبار المزارعين يكبّر الحروف والأزرار على أي جهاز، من صفحة التفضيلات.',
  'about.pressTitle': 'الصحافة والشراكات',
  'sweep.quality.title': 'وعد الجودة',
  'sweep.quality.lead': 'ما يحمي طلبك، قاعدة تلو الأخرى، كما يعمل فعلًا — وما ليس موعودًا به، بوضوح.',
  'sweep.quality.rulesTitle': 'القواعد',
  'sweep.quality.disputesTitle': 'عندما يكون في الطلب خلل',
  'sweep.quality.disputesPerStore': 'تقرر كل منظمة ما إذا كان متجرها يقبل النزاعات. حيث يقبلها:',
  'sweep.quality.disputesOff': 'لم تفعّل هذه المنظمة النزاعات في هذا المتجر: لا يمكن فتح مشكلة كنزاع هنا.',
  'sweep.quality.disputesUnknown': 'تعذّرت قراءة ما إذا كان هذا المتجر يقبل النزاعات الآن.',
  'sweep.quality.rule.listing_grade': 'يُصنَّف مرة واحدة، عند العرض. درجة الدفعة هي الدرجة التي أكدتها المنظمة عند عرضها.',
  'sweep.quality.rule.window_online': 'الدفع عبر الإنترنت: {hours} ساعة بعد التسليم للإبلاغ عن مشكلة، وهي المدة نفسها لكل أنواع المنتجات. قل «لقد استلمته» فيُفرج عن الدفعة للمنظمة حينها؛ وإذا لم يُبلَّغ عن شيء، يكتمل الطلب تلقائيًا عند انتهاء المهلة.',
  'sweep.quality.rule.no_window_cod': 'الدفع عند التسليم: لا توجد مهلة ولا يُحتجز شيء. قول «لقد استلمته» يُغلق الطلب.',
  'sweep.quality.rule.dispute_text': 'تُفتح المشكلة كنزاع، كتابةً، من صفحة الطلب.',
  'sweep.quality.rule.whole_payment_held': 'ما دام النزاع مفتوحًا، تبقى دفعة الطلب كاملة في الضمان — وليس الجزء المتنازع عليه فقط. الطلب المدفوع عند التسليم ليس له شيء في الضمان.',
  'sweep.quality.rule.moderator_decides': 'يقرر النزاعَ مشرفُ المنظمة أو مكتبُ المنصة.',
  'sweep.quality.rule.resolution_types': 'ينتهي النزاع بأحد أربعة قرارات: استرداد كامل، أو استرداد جزئي بالمبلغ الذي يقرره المشرف، أو استبدال، أو رفض النزاع.',
  'sweep.quality.rule.refund_to_source': 'يعود الاسترداد إلى مصدر المال — كاملًا، أو بالمبلغ المقرَّر.',
  'sweep.quality.rule.cancel_per_order': 'ما إذا كان الطلب ما يزال قابلًا للإلغاء يظهر في صفحة ذلك الطلب. الطلب المدفوع الملغى يُسترد بالكامل.',
  'sweep.quality.rule.trace_entry': 'الدفعة ذات التتبع المنشور يمكن لأي شخص التحقق منها: اكتب الرمز الموجود على العبوة.',
