  'sweep.footer.grievances': 'الشكاوى',
  'sweep.refusal.liveModules': 'لا تسرد هذه الصفحة الوحدات على أنها نشطة: الدفع عبر الإنترنت والتسليم والتتبع تفعّلها كل منظمة، والائتمان والتأمين غير متاحين بعد.',
  'sweep.refusal.moneyTrace': 'صفحة التتبع لا تُظهر أين ذهب المال: إنها تُظهر رحلة الدفعة، ولا تُظهر شخصًا أو دفعة مالية أبدًا.',
  'sweep.refusal.escrowEveryOrder': 'ليس كل طلب يمر عبر الضمان: الطلب المدفوع عند التسليم ليس له دفعة عبر الإنترنت لاحتجازها.',
  'sweep.refusal.voiceLanguages': 'لا شيء هنا يُنطق بصوت عالٍ، ولا توجد قائمة رمز قصير، ولا تُقدَّم إلا اللغات الموجودة في قائمة اللغات.',
  'sweep.refusal.regrade': 'لا يوجد تصنيف ثانٍ عند الشحن: الدرجة هي المؤكدة عند العرض.',
  'sweep.refusal.tolerance': 'لا توجد قاعدة تفاوت للوزن أو الرطوبة، ولا يُحسب أي استرداد بمعادلة: الاسترداد الجزئي مبلغ يقرره المشرف.',
  'sweep.refusal.perishables': 'لا توجد مهلة أقصر للمنتجات سريعة التلف: مهلة واحدة تنطبق على كل طلب مدفوع عبر الإنترنت.',
  'sweep.refusal.disputePhotos': 'النزاع نص مكتوب فقط: لا صور ولا لوحة أدلة مشتركة.',
  'sweep.refusal.escrowFreeze': 'النزاع لا يحتجز جزءًا من الدفعة فقط أبدًا: تبقى دفعة الطلب كاملة في الضمان ما دام مفتوحًا.',
  'sweep.refusal.futureCredits': 'لا يُقدَّم رصيد لطلب مستقبلي كتعويض.',
  'sweep.refusal.resolvedInDays': 'لا يُوعد بمدة لحل النزاع: لم تُحدَّد أي مدة.',
  'sweep.refusal.noFinePrint': 'هذه الصفحة ليست القصة الكاملة لأي طلب بعينه: صفحة ذلك الطلب تذكر ما ينطبق عليه.',
  'sweep.refusal.feeLadder': 'لا توجد صفحة لسلّم رسوم الإلغاء: ما إذا كان الطلب ما يزال قابلًا للإلغاء يظهر على ذلك الطلب.',
  'sweep.refusal.traceDemo': 'لا يُعرض مثال تتبع مباشر: لم تُعدّ أي دفعة عرض توضيحي عامة.',
  'sweep.refusal.regulatedPartner': 'لا يُدّعى أن مدفوعات الطلبات موجودة لدى شريك خاضع للتنظيم أو خارج حسابات المنصة نفسها: لا يوجد اتفاق كهذا.',
  'sweep.refusal.independentAudit': 'لا يُوصف الدفتر بأنه مدقَّق بشكل مستقل: لم يُنشر أي تدقيق مستقل.',
  'sweep.refusal.encryption': 'لا يُقدَّم هنا أي ادعاء بشأن التشفير: كيفية حماية البيانات المخزَّنة والمنقولة حقيقة تتعلق بإعداد الاستضافة، ولا تستطيع هذه الصفحة إظهارها.',
  'sweep.refusal.consentDocuments': 'لا يُدّعى أن المستندات لا تُفتح إلا ضمن موافقة مسجّلة: لم يُتحقق من ذلك.',
  'sweep.refusal.sellData': 'لا يُطبع هنا أي وعد بشأن بيع البيانات الشخصية: ذلك التزام على الشركة أن تقدّمه كتابةً.',
  'sweep.refusal.certAudits': 'لا يُوصف أي تدقيق اعتماد بأنه جارٍ: لم يُنشر أي تدقيق.',
  'sweep.refusal.proxiedCalls': 'واجهة المتجر هذه لا تقدّم مكالمات هاتفية، لذا لا تُجرى أي مكالمة عبر رقم مخفي.',
  'sweep.refusal.disclosureProgramme': 'لا يوجد برنامج منشور للإبلاغ عن الثغرات؛ ويُطبع صندوق بريد الأمان بمجرد نشره.',
  'sweep.refusal.grievanceFigures': 'لا تُطبع مدة إقرار أو حل ما لم تكن منشورة، ولا يُستشهد هنا بأي قانون: تحديد القواعد المنطبقة من شأن محامٍ.',
  'sweep.refusal.helpSearch': 'لا يوجد بحث في هذه الإجابات: إنها تتسع لصفحة واحدة.',
  'sweep.refusal.voice': 'لا شيء هنا يستمع أو يتكلم: لا يوجد بحث صوتي ولا إجابة منطوقة.',
  'sweep.refusal.shortCode': 'لا توجد قائمة رمز قصير ولا طلب عبر رقم معاودة الاتصال.',
  'sweep.refusal.licenceUpload': 'لا يُرفع أي ترخيص هنا: المدخلات الزراعية الخاضعة للتنظيم لا تُباع في واجهة المتجر هذه.',
  'sweep.refusal.versionedAnswers': 'لا تُحفظ الصياغات السابقة لهذه الإجابات لتعود إليها: هذه هي الصياغة الحالية.',
  'sweep.refusal.phoneLine': 'لا يوجد خط هاتفي.',
  'sweep.refusal.ticket': 'لا توجد تذكرة لفتحها، ولا تصل كل الرسائل إلى نظام تذاكر واحد.',
  'sweep.refusal.paging': 'لا يُستدعى أحد على مدار الساعة: المشكلة في طلب تُفتح على ذلك الطلب.',
